gPB(){return"\u0936\u093e\u0916\u093e\u090f\u0902 \u0914\u0930 \u0917\u094b\u0926\u093e\u092e"},
gPD(){return"\u090f\u0915\u0932 \u0938\u094d\u0925\u093e\u0928 \u2014 \u092e\u0932\u094d\u091f\u0940-\u092c\u094d\u0930\u093e\u0902\u091a \u092e\u094b\u0921 \u0905\u0928\u0932\u0949\u0915 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092f\u0939\u093e\u0902 \u090f\u0915 \u0936\u093e\u0916\u093e \u091c\u094b\u0921\u093c\u0947\u0902"},
gPC(){return"\u0938\u094d\u0925\u093e\u0928 \u0914\u0930 \u0917\u094b\u0926\u093e\u092e \u092a\u094d\u0930\u092c\u0902\u0927\u093f\u0924 \u0915\u0930\u0947\u0902"},
gTV(){return"\u092c\u0948\u0915\u0905\u092a \u0914\u0930 \u0938\u093f\u0902\u0915 \u0915\u0947 \u0932\u093f\u090f \u0938\u0940\u0927\u0940 \u092b\u093c\u093e\u0907\u0932 \u092a\u0939\u0941\u0902\u091a \u091a\u093e\u0939\u093f\u090f \u0914\u0930 \u092f\u0939 \u0905\u092d\u0940 \u0935\u0947\u092c \u092c\u093f\u0932\u094d\u0921 \u092e\u0947\u0902 \u0909\u092a\u0932\u092c\u094d\u0927 \u0928\u0939\u0940\u0902 \u0939\u0948\u0964 \u0907\u0938\u0915\u0947 \u0932\u093f\u090f \u092e\u094b\u092c\u093e\u0907\u0932 \u092f\u093e \u0921\u0947\u0938\u094d\u0915\u091f\u0949\u092a \u0910\u092a \u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0947\u0902\u0964"},
gW1(){return"\u0915\u0902\u092a\u0928\u0940 \u092a\u094d\u0930\u094b\u092b\u093c\u093e\u0907\u0932"},
